def transform(grid):
    from collections import Counter, deque
    h=len(grid); w=len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    seen=set()
    for r in range(h):
        for c in range(len(grid[r])):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<len(grid[yy]) and (yy,xx) not in seen and grid[yy][xx]==col:
                        seen.add((yy,xx)); q.append((yy,xx))
            y0=min(y for y,x in cells); y1=max(y for y,x in cells)
            x0=min(x for y,x in cells); x1=max(x for y,x in cells)
            area=(y1-y0+1)*(x1-x0+1)
            # Output objects are the solid/near-solid rectangles; isolated and
            # irregular intrusions are noise. Exact dimensions preserved.
            if len(cells)>=3 and len(cells)/area>=0.70:
                for y in range(y0,y1+1):
                    for x in range(x0,x1+1): out[y][x]=col
    return out

