 "path": "programs/task-756ae3db.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]

    # Locate the two edge bars. The puzzle uses matching short runs on
    # opposite edges, with sparse signal pixels in the interior.
    top = [(0, c) for c, v in enumerate(grid[0]) if v != bg]
    bottom = [(h - 1, c) for c, v in enumerate(grid[-1]) if v != bg]
    if not top or not bottom:
        return out
    top_cols = [c for _, c in top]
    bottom_cols = [c for _, c in bottom]
    signal = [(r, c, grid[r][c]) for r in range(1, h - 1)
              for c in range(w) if grid[r][c] != bg]
    if not signal:
        return out
    color = signal[0][2]

    # Seed pixels are marked as completed, and the corresponding offset
    # in each edge run is extended toward the seed-facing half of the grid.
    for r, c, v in signal:
        out[r][c] = 4
        if c in top_cols:
            i = top_cols.index(c)
            if i < len(bottom_cols):
                bc = bottom_cols[i]
                for rr in range(1, r):
                    out[rr][c] = v
                for rr in range(r + 1, h - 1):
                    out[rr][bc] = v
        elif c in bottom_cols:
            i = bottom_cols.index(c)
            if i < len(top_cols):
                tc = top_cols[i]
                for rr in range(1, r):
                    out[rr][tc] = v
                for rr in range(r + 1, h - 1):
                    out[rr][c] = v
        else:
            # A seed within a bar's horizontal span activates that aligned
            # column, extending from the nearest bar toward the seed.
            nearest = min(top_cols + bottom_cols, key=lambda x: abs(x - c))
            if nearest in top_cols:
                for rr in range(1, r):
                    out[rr][nearest] = v
            else:
                for rr in range(r + 1, h - 1):
                    out[rr][nearest] = v
    return out
