 def transform(grid):
    """Expand square grid into four 90-degree rotations around a center."""
    n = len(grid)
    if not n or any(len(row) != n for row in grid):
        raise ValueError("expected a non-empty square grid")

    def rotate_clockwise(g):
        return [list(row) for row in zip(*g[::-1])]

    rotations = [grid]
    for _ in range(3):
        rotations.append(rotate_clockwise(rotations[-1]))
    return ([rotations[0][i] + rotations[1][i] for i in range(n)] +
            [rotations[3][i] + rotations[2][i] for i in range(n)])


