from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg}
    comps=[]
    while pts:
        stack=[pts.pop()]; comp=set(stack)
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in pts: pts.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    # The largest colored component is the prototype; isolated marks are copy anchors.
    source=max(comps,key=len)
    r0=min(r for r,c in source); r1=max(r for r,c in source)
    c0=min(c for r,c in source); c1=max(c for r,c in source)
    cr=(r0+r1)//2; cc=(c0+c1)//2
    stencil={(r-cr,c-cc):grid[r][c] for r,c in source}
    anchors=[next(iter(x)) for x in comps if x is not source and len(x)==1]
    out=[row[:] for row in grid]
    for r,c in anchors:
        for (dr,dc),v in stencil.items():
            rr,ccc=r+dr,c+dc
            if 0<=rr<h and 0<=ccc<w: out[rr][ccc]=v
    return out


